"use strict";

const googleDriveAutomator = () => {
  const keywords = ["uc?", "export=download", "/file/d"];
  const pageUrl = window.location.href;
  const domainList = ["drive", "docs"];
  const domainIndex = domainList.findIndex((domain) =>
    pageUrl.includes(`//${domain}.`),
  );
  if (domainIndex === -1) return;

  // Exit if the URL does not belong to allowed domains
  // Check for keyword matches
  if (keywords.some((keyword) => pageUrl.includes(keyword))) {
    const downloadLink = document.getElementById("uc-download-link");
    if (downloadLink) {
      downloadLink.click();
    }
    return;
  }
  // Handle specific case for Google Drive file links
  if (pageUrl.includes("google.com/file/d/")) {
    const downloadId = pageUrl.split("/").slice(-2, -1)[0]; // Get the download ID
    const targetUrl = `https://${
      domainList[domainIndex]
    }.google.com/u/0/uc?id=${downloadId}&export=download`;
    window.location.href = targetUrl; // Redirect to the download URL
    return;
  }
};
document.addEventListener("DOMContentLoaded", googleDriveAutomator);
//GM_registerMenuCommand("Initiate Download", googleDriveAutomator);
setTimeout(googleDriveAutomator, 300);

