function parseTextToJSON(text) {
  const result = [];

  // Extract file information
  const fileRegex = /- \[([^\]]+)\]\(([^:]+)\):\s*(.*)/g;
  let match;

  while ((match = fileRegex.exec(text)) !== null) {
    result.push({
      id: match[1],
      path: match[2].trim(),
      description: match[3].trim()
    });
  }

  return result;
}

